bool is_convex = true;
if (polygon.size() < 3) return false;
std::vector<CGAL::Point_2> points = polygon;
CGAL::Orientation orientation = CGAL::COLLINEAR;
for (int i = 0; i < points.size(); i++) {
    CGAL::Point_2 p1 = points[i];
    CGAL::Point_2 p2 = points[(i + 1) % points.size()];
    CGAL::Point_2 p3 = points[(i + 2) % points.size()];
    CGAL::Orientation o = CGAL::orientation(p1, p2, p3);
    if (o == CGAL::COLLINEAR) continue;
    if (orientation == CGAL::COLLINEAR) orientation = o;
    else if (orientation != o) {
        is_convex = false;
        break;
    }
}
return is_convex;

